- Load a model from a file: AIModelManager model\_mngr; AIModelDescription model\_desc; AIConfig config; /\* Check whether the input file path is valid. Path: The value can contain uppercase letters, lowercase letters, digits, and underscores (\_). File name: The value can contain uppercase letters, lowercase letters, digits, underscores (\_), and dots (.). \*/ model\_desc.set\_path(MODEL\_PATH); model\_desc.set\_name(MODEL\_NAME); model\_desc.set\_type(0); vector<AIModelDescription> model\_descs; model\_descs.push\_back(model\_desc); // AIModelManager Init AIStatus ret = model\_mngr.Init(config, model\_descs); if (SUCCESS != ret) { printf("AIModelManager Init failed. ret = %d\n", ret);

- return -1; }
- <span id="page-338-0"></span>● Load a model from memory: AIModelManager model\_mngr; AIModelDescription model\_desc; vector<AIModelDescription> model\_descs; AIConfig config; model\_desc.set\_name(MODEL\_NAME); model\_desc.set\_type(0); char \*model\_data = nullptr; uint32\_t model\_size = 0; ASSERT\_EQ(true, Utils::ReadFile(MODEL\_PATH.c\_str(), model\_data, model\_size)); model\_desc.set\_data(model\_data,model\_size); model\_desc.set\_size(model\_size); AIStatus ret = model\_mngr.Init(config, model\_descs); if (SUCCESS != ret) { printf("AIModelManager Init failed. ret = %d\n", ret); return -1; } }

