To encode multiple images into a video, call **[RunVenc](#page-501-0)** to encode the video by using the same instance after creating an instance by calling **[CreateVenc](#page-499-0)**, and then call **[DestroyVenc](#page-503-0)** to release the instance.

In this example, the VENC API is called to encode YUV images into H.265 or H.264 streams.

std::string vencOutFileName("venc.bin"); std::shared\_ptr<FILE> vencOutFile(nullptr); void VencCallBackDumpFile(struct VencOutMsg\* vencOutMsg, void\* userData) { if (vencOutFile.get() == nullptr) { HIAI\_ENGINE\_LOG(HIAI\_VENC\_CTL\_ERROR, "get venc out file fail!"); return; } fwrite(vencOutMsg->outputData, 1, vencOutMsg->outputDataSize, vencOutFile.get()); fflush(vencOutFile.get()); } /\* \* venc new interface to achieve venc basic functions. \*/ void TEST\_VENC() { std::shared\_ptr<FILE> fpIn(fopen(g\_inFileName, "rb"), fclose); vencOutFile.reset(fopen(vencOutFileName.c\_str(), "wb"), fclose); if (fpIn.get() == nullptr || vencOutFile.get() == nullptr) { HIAI\_ENGINE\_LOG(HIAI\_OPEN\_FILE\_ERROR, "open open venc in/out file failed.");

 return; } fseek(fpIn.get(), 0, SEEK\_END); uint32\_t fileLen = ftell(fpIn.get()); fseek(fpIn.get(), 0, SEEK\_SET); struct VencConfig vencConfig; vencConfig.width = g\_width; vencConfig.height = g\_high; vencConfig.codingType = g\_format; vencConfig.yuvStoreType = g\_yuvStoreType; vencConfig.keyFrameInterval = 16; vencConfig.vencOutMsgCallBack = VencCallBackDumpFile; vencConfig.userData = nullptr; int32\_t vencHandle = CreateVenc(&vencConfig); if (vencHandle == -1) { HIAI\_ENGINE\_LOG(HIAI\_VENC\_CTL\_ERROR, "CreateVenc fail!"); return; } // input 16 frames once uint32\_t inDataLenMaxOnce = g\_width \* g\_high \* 3 / 2; std::shared\_ptr<char> inBuffer(static\_cast<char\*>(malloc(inDataLenMaxOnce)), free); if (inBuffer.get() == nullptr) { HIAI\_ENGINE\_LOG(HIAI\_OPEN\_FILE\_ERROR, "alloc input buffer failed"); DestroyVenc(vencHandle); return; } uint32\_t inDataUnhandledLen = fileLen; auto start = std::chrono::system\_clock::now(); uint32\_t frameCount = 0; while (inDataUnhandledLen > 0) { uint32\_t inDataLen = inDataUnhandledLen; if (inDataUnhandledLen > inDataLenMaxOnce) { inDataLen = inDataLenMaxOnce; } inDataUnhandledLen -= inDataLen; uint32\_t readLen = fread(inBuffer.get(), 1, inDataLen, fpIn.get()); if (readLen != inDataLen) { HIAI\_ENGINE\_LOG(HIAI\_OPEN\_FILE\_ERROR, "error in read input file"); DestroyVenc(vencHandle); return; } struct VencInMsg vencInMsg; vencInMsg.inputData = inBuffer.get(); vencInMsg.inputDataSize = inDataLen; vencInMsg.keyFrameInterval = 16; vencInMsg.forceIFrame = 0; vencInMsg.eos = 0; if (RunVenc(vencHandle, &vencInMsg) == -1) { HIAI\_ENGINE\_LOG(HIAI\_VENC\_CTL\_ERROR, "call video encode fail"); break; } ++frameCount; } auto end = std::chrono::system\_clock::now(); auto duration = std::chrono::duration\_cast<std::chrono::microseconds>(end - start); size\_t timeCount = static\_cast<size\_t>(duration.count()); HIAI\_ENGINE\_LOG("Total frame count: %u", frameCount); HIAI\_ENGINE\_LOG("Time cost: %lu us", timeCount);

